package com.example.yuejie;
import android.content.*;import android.graphics.*;import android.widget.*;import java.io.*;import java.net.*;import java.security.*;import java.util.*;import java.util.concurrent.*;
/** Static bitmap thumbnails only. Signed URLs remain intact; remote HTML is never rendered. */
final class CommentImages {
 static final long LIMIT=30L*1024*1024;static final ExecutorService IO=Executors.newFixedThreadPool(2);
 static final android.util.LruCache<String,Bitmap> MEMORY=new android.util.LruCache<String,Bitmap>(6*1024*1024){protected int sizeOf(String k,Bitmap b){return b.getAllocationByteCount();}};
 static final Map<String,List<java.lang.ref.WeakReference<ImageView>>> pending=new HashMap<>();
 static Bitmap load(Context c,String url)throws Exception{if(!url.startsWith("https://"))throw new IOException("Unsupported image URL");File folder=new File(c.getCacheDir(),"paragraph-images");folder.mkdirs();String key=ProtocolCrypto.hex(MessageDigest.getInstance("SHA-256").digest(ProtocolCrypto.utf(url)));File file=new File(folder,key);if(file.isFile()){Bitmap b=BitmapFactory.decodeFile(file.getPath());if(b!=null){file.setLastModified(System.currentTimeMillis());return b;}file.delete();}
  HttpURLConnection con=(HttpURLConnection)new URL(url).openConnection();con.setConnectTimeout(8000);con.setReadTimeout(12000);byte[] bytes;try{con.setRequestProperty("User-Agent","Mozilla/5.0");if(con.getResponseCode()!=200)throw new IOException("图片暂不可用");try(InputStream in=con.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] block=new byte[8192];int n;while((n=in.read(block))!=-1){if(out.size()+n>8*1024*1024)throw new IOException("图片过大");out.write(block,0,n);}bytes=out.toByteArray();}}finally{con.disconnect();}
  BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth<=0||bounds.outHeight<=0)throw new IOException("图片格式暂不支持");BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/options.inSampleSize>1400)options.inSampleSize*=2;Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(b==null)throw new IOException("图片加载失败");synchronized(CommentImages.class){try(OutputStream out=new FileOutputStream(file)){b.compress(Bitmap.CompressFormat.JPEG,88,out);}File[] files=folder.listFiles();if(files!=null){Arrays.sort(files,(a,z)->Long.compare(a.lastModified(),z.lastModified()));long total=0;for(File f:files)total+=f.length();for(File f:files){if(total<=LIMIT)break;long size=f.length();if(f.delete())total-=size;}}}return b;
 }
 static android.graphics.drawable.Drawable placeholder(Context c,String label){return new android.graphics.drawable.Drawable(){final Paint p=new Paint(3);public void draw(Canvas canvas){p.setColor(0xff8c8a7b);p.setTextSize(PaperUi.dp(c,12));p.setTextAlign(Paint.Align.CENTER);canvas.drawText(label,getBounds().centerX(),getBounds().centerY()-(p.ascent()+p.descent())/2,p);}public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return PixelFormat.TRANSLUCENT;}};}
 static void show(Context c,String url,ImageView view){view.setTag(url);Bitmap cached=MEMORY.get(url);if(cached!=null){view.setImageBitmap(cached);return;}if(view.getContentDescription()!=null&&view.getContentDescription().toString().contains("图片"))view.setImageDrawable(placeholder(c.getApplicationContext(),"加载图片…"));synchronized(pending){List<java.lang.ref.WeakReference<ImageView>> views=pending.get(url);if(views!=null){views.add(new java.lang.ref.WeakReference<>(view));return;}views=new ArrayList<>();views.add(new java.lang.ref.WeakReference<>(view));pending.put(url,views);}Context app=c.getApplicationContext();IO.execute(()->{Bitmap b=null;try{b=load(app,url);MEMORY.put(url,b);}catch(Exception ignored){}final Bitmap result=b;final List<java.lang.ref.WeakReference<ImageView>> listeners;synchronized(pending){listeners=pending.remove(url);}NovelApi.MAIN.post(()->{if(listeners!=null)for(java.lang.ref.WeakReference<ImageView> ref:listeners){ImageView v=ref.get();if(v!=null&&url.equals(v.getTag())){if(result!=null){v.setImageBitmap(result);v.setContentDescription("段评图片，点击查看大图");}else if(v.getContentDescription()!=null&&v.getContentDescription().toString().contains("图片")){v.setContentDescription("图片加载失败，点击重试");v.setImageDrawable(placeholder(app,"加载失败，点击重试"));}}}});});}
}
